import{_ as n,a0 as s,w as i,s as c,ao as l,I as p,x as a,a1 as r,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"使用 Linux 的 strace 命令跟踪/调试程序的常用选项 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 的 strace 命令跟踪/调试程序的常用选项 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 的 strace 命令跟踪/调试程序的常用选项 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 的 strace 命令跟踪/调试程序的常用选项 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command","title":"使用 Linux 的 strace 命令跟踪/调试程序的常用选项","tag":"201409","desc":""},"relativePath":"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command.md","filePath":"[post].md"}'),d={name:"201409/20140819 8 Options to Trace or Debug Programs using Linux strace Command.md"};function m(u,e,h,g,x,f){const t=s("Link");return i(),c("div",null,[e[13]||(e[13]=l(`<h1 id="使用-linux-的-strace-命令跟踪-调试程序的常用选项" tabindex="-1">使用 Linux 的 strace 命令跟踪/调试程序的常用选项 <a class="header-anchor" href="#使用-linux-的-strace-命令跟踪-调试程序的常用选项" aria-label="Permalink to “使用 Linux 的 strace 命令跟踪/调试程序的常用选项”">​</a></h1><p>在调试的时候，strace能帮助你追踪到一个程序所执行的系统调用。当你想知道程序和操作系统如何交互的时候，这是极其方便的，比如你想知道执行了哪些系统调用，并且以何种顺序执行。</p><p>这个简单而又强大的工具几乎在所有的Linux操作系统上可用，并且可被用来调试大量的程序。</p><h3 id="命令用法" tabindex="-1">命令用法 <a class="header-anchor" href="#命令用法" aria-label="Permalink to “命令用法”">​</a></h3><p>让我们看看strace命令如何追踪一个程序的执行情况。</p><p>最简单的形式，strace后面可以跟任何命令。它将列出许许多多的系统调用。一开始，我们并不能理解所有的输出，但是如果你正在寻找一些特殊的东西，那么你应该能从输出中发现它。</p><p>让我们来看看简单命令ls的系统调用跟踪情况。</p><pre><code>raghu@raghu-Linoxide ~ $ strace ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/01.strace_ls.png" alt="Stracing ls command"></p><p>这是strace命令输出的前几行。其他输出被截去了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/02.strace_ls_write.png" alt="Strace write system call (ls)"></p><p>上面的输出部分展示了write系统调用，它把当前目录的列表输出到标准输出。</p><p>下面的图片展示了使用ls命令列出的目录内容（没有使用strace）。</p><pre><code>raghu@raghu-Linoxide ~ $ ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/03.ls_.png" alt="ls command output"></p><h4 id="选项1-寻找被程序读取的配置文件" tabindex="-1">选项1 寻找被程序读取的配置文件 <a class="header-anchor" href="#选项1-寻找被程序读取的配置文件" aria-label="Permalink to “选项1 寻找被程序读取的配置文件”">​</a></h4><p>Strace 的用法之一（除了调试某些问题以外）是你能找到被一个程序读取的配置文件。例如，</p><pre><code>raghu@raghu-Linoxide ~ $ strace php 2&gt;&amp;1 | grep php.ini
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/04.strace_php_configuration.png" alt="Strace config file read by program"></p><h4 id="选项2-跟踪指定的系统调用" tabindex="-1">选项2 跟踪指定的系统调用 <a class="header-anchor" href="#选项2-跟踪指定的系统调用" aria-label="Permalink to “选项2 跟踪指定的系统调用”">​</a></h4><p>strace命令的-e选项仅仅被用来展示特定的系统调用（例如，open，write等等）</p><p>让我们跟踪一下cat命令的‘open’系统调用。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -e open cat dead.letter
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/05.strace_open_systemcall.png" alt="Stracing specific system call (open here)"></p><h4 id="选项3-跟踪进程" tabindex="-1">选项3 跟踪进程 <a class="header-anchor" href="#选项3-跟踪进程" aria-label="Permalink to “选项3 跟踪进程”">​</a></h4><p>strace不但能用在命令上，而且通过使用-p选项能用在运行的进程上。</p><pre><code>raghu@raghu-Linoxide ~ $ sudo strace -p 1846
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/06.strace_process.png" alt="Strace a process"></p><h4 id="选项4-strace的统计概要" tabindex="-1">选项4 strace的统计概要 <a class="header-anchor" href="#选项4-strace的统计概要" aria-label="Permalink to “选项4 strace的统计概要”">​</a></h4><p>它包括系统调用的概要，执行时间，错误等等。使用-c选项能够以一种整洁的方式展示：</p><pre><code>raghu@raghu-Linoxide ~ $ strace -c ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/07.strace_summary.png" alt="Strace summary display"></p><h4 id="选项5-保存输出结果" tabindex="-1">选项5 保存输出结果 <a class="header-anchor" href="#选项5-保存输出结果" aria-label="Permalink to “选项5 保存输出结果”">​</a></h4><p>通过使用-o选项可以把strace命令的输出结果保存到一个文件中。</p><pre><code>raghu@raghu-Linoxide ~ $ sudo strace -o process_strace -p 3229
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/08.strace_output_file.png" alt="Strace a process"></p><p>之所以以sudo来运行上面的命令，是为了防止用户ID与所查看进程的所有者ID不匹配的情况。</p><h3 id="选项6-显示时间戳" tabindex="-1">选项6 显示时间戳 <a class="header-anchor" href="#选项6-显示时间戳" aria-label="Permalink to “选项6 显示时间戳”">​</a></h3><p>使用-t选项，可以在每行的输出之前添加时间戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -t ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/09.strace_timestamp.png" alt="Timestamp before each output line"></p><h4 id="选项7-更精细的时间戳" tabindex="-1">选项7 更精细的时间戳 <a class="header-anchor" href="#选项7-更精细的时间戳" aria-label="Permalink to “选项7 更精细的时间戳”">​</a></h4><p>-tt选项可以展示微秒级别的时间戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -tt ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/010.strace_finer_timestamp.png" alt="Time - Microseconds"></p><p>-ttt也可以向上面那样展示微秒级的时间戳，但是它并不是打印当前时间，而是显示自从epoch（译注：1970年1月1日00:00:00 UTC）以来的所经过的秒数。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -ttt ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/011.strace_epoch_seconds.png" alt="Seconds since epoch"></p><h4 id="选项8-相对时间" tabindex="-1">选项8 相对时间 <a class="header-anchor" href="#选项8-相对时间" aria-label="Permalink to “选项8 相对时间”">​</a></h4><p>-r选项展示系统调用之间的相对时间戳。</p><pre><code>raghu@raghu-Linoxide ~ $ strace -r ls
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/012.strace_relative-time.png" alt="Relative Timestamp"></p><hr>`,53)),p("p",null,[e[1]||(e[1]=a("via: ",-1)),r(t,{href:"http://linoxide.com/linux-command/linux-strace-command-examples/"},{default:o(()=>[...e[0]||(e[0]=[a("http://linoxide.com/linux-command/linux-strace-command-examples/",-1)])]),_:1})]),p("p",null,[e[5]||(e[5]=a("作者：",-1)),r(t,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[2]||(e[2]=[a("Raghu",-1)])]),_:1}),e[6]||(e[6]=a(" 译者：",-1)),r(t,{href:"https://github.com/guodongxiaren"},{default:o(()=>[...e[3]||(e[3]=[a("guodongxiaren",-1)])]),_:1}),e[7]||(e[7]=a(" 校对：",-1)),r(t,{href:"https://github.com/wxy"},{default:o(()=>[...e[4]||(e[4]=[a("wxy",-1)])]),_:1})]),p("p",null,[e[10]||(e[10]=a("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[a("LCTT",-1)])]),_:1}),e[11]||(e[11]=a(" 原创翻译，",-1)),r(t,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[a("Linux中国",-1)])]),_:1}),e[12]||(e[12]=a(" 荣誉推出",-1))])])}const b=n(d,[["render",m]]);export{T as __pageData,b as default};
